import"./chunk-2NFLSA4Y.js";var s={gasLaws:{theory:{concept:"[[The gas laws describe how the pressure p, the volume V and the absolute temperature T of a fixed amount of gas are related: p\u2081V\u2081 / T\u2081 = p\u2082V\u2082 / T\u2082.]] If one of the three quantities is kept constant, the other two follow a simpler law."},section:{particles:{title:"Where pressure comes from",text:"The particles of air around you fly at about 500 m/s \u2014 faster than a passenger jet \u2014 and each square centimetre of your skin is hit about 10\xB2\xB3 times every second. Each hit is tiny, but together they make the air pressure of about 100 kPa. Watch the piston: the more often and the harder the particles hit it, the bigger the pressure."},boyle:{title:"Boyle's law: squeezing at constant temperature",text:"Keep the temperature constant and squeeze the gas into half the volume: the particles are twice as crowded and hit the walls twice as often, so the pressure doubles. [[p\xB7V stays constant: p\u2081\xB7V\u2081 = p\u2082\xB7V\u2082.]] Robert Boyle (and, independently, Edme Mariotte) found this in the 1660s. On the p\u2013V graph this process is a curve, a hyperbola."},charles:{title:"Charles's law: heating at constant pressure",text:"If the piston can move freely, the pressure stays the same. Heat the gas and the faster particles push the piston out until the pressure is back to its old value: the volume grows in proportion to the kelvin temperature, V / T = constant. From 300 K to 600 K the volume doubles. A balloon taken from a warm room into the frost shrinks for the same reason."},gayLussac:{title:"Gay-Lussac's law: heating in a closed container",text:"Lock the piston so the volume cannot change, then heat the gas. The particles hit the walls harder and more often, so the pressure grows in proportion to the kelvin temperature: p / T = constant. That is why aerosol cans must never be thrown into a fire, and why tyre pressure is higher on a hot day."},kelvin:{title:"Why kelvin?",text:"[[The gas laws work only with the absolute temperature, measured in kelvin: T = t + 273.15.]] At 0 K \u2014 absolute zero, \u2212273.15 \xB0C \u2014 the particles would have the least possible motion, and an ideal gas would have no pressure at all. Doubling the temperature means doubling it in kelvin: 300 K \u2192 600 K (27 \xB0C \u2192 327 \xB0C), not 20 \xB0C \u2192 40 \xB0C."},ideal:{title:"One law for all gases",text:"[[The three laws combine into the ideal gas law p\xB7V = n\xB7R\xB7T, where n is the amount of gas in moles and R = 8.314 J/(mol\xB7K) is the gas constant.]] Remarkably, it does not matter which gas it is: a mole of helium, of air or of carbon dioxide at the same temperature and volume has the same pressure. Light particles simply move faster: v_rms = \u221A(3RT/M). Real gases follow the law well unless they are very dense or close to turning into a liquid."},everyday:{title:"Gas laws around us",text:"A bicycle pump squeezes air (Boyle) and gets warm. A hot-air balloon rises because heated air expands and becomes lighter (Charles). A pressure cooker raises the pressure in a closed pot (Gay-Lussac). Divers must breathe out while rising, because the air in their lungs expands as the water pressure falls."},check:{title:"Check your understanding",text:"At constant temperature the volume is halved. What happens to the pressure? (It doubles.) At constant pressure a gas is heated from 300 K to 450 K. What happens to its volume? (It grows 1.5 times.) A closed can is heated from 27 \xB0C to 327 \xB0C. What happens to the pressure? (It doubles \u2014 300 K to 600 K.) Do helium and air at the same T, V and n have the same pressure? (Yes.) Test each answer in the simulation."}},formula:{boyle:"Boyle's law: constant temperature",charles:"Charles's law: constant pressure",gayLussac:"Gay-Lussac's law: constant volume",kelvin:"Kelvin from degrees Celsius",ideal:"The ideal gas law",combined:"The combined gas law for a fixed amount of gas",speed:"Root-mean-square speed of the particles (M: molar mass)"},variable:{pressure:"Pressure",volume:"Volume",temperature:"Absolute temperature",amount:"Amount of gas",constant:"Gas constant",molarMass:"Molar mass (mass of one mole)"},assumption:{ideal:"Ideal gas: the particles have no size and do not attract each other.",equilibrium:"The process is slow: the gas is always in equilibrium, and heat flows in or out as needed to follow the chosen temperature.",scale:"The picture shows a few dozen particles in two dimensions, moving far more slowly than real ones; a litre of air holds about 2.5\xB710\xB2\xB2 molecules."},param:{process:"Process",volume:"Volume at the start",temperature:"Temperature at the start",finalVolume:"Volume at the end",finalTemperature:"Temperature at the end",amount:"Amount of gas",gas:"Gas",timeStep:"Time step"},hint:{process:"Which quantity stays constant while the gas changes.",temperature:"Absolute temperature in kelvin: 300 K is 27 \xB0C.",amount:"More gas means more particles hitting the walls.",gas:"The gas changes how fast the particles move \u2014 but not the pressure."},option:{isothermal:"Squeeze or expand (T constant)",isobaric:"Heat or cool, free piston (p constant)",isochoric:"Heat or cool, locked piston (V constant)"},gas:{air:"Air",helium:"Helium",carbonDioxide:"Carbon dioxide"},measure:{pressure:"Pressure",volume:"Volume",temperature:"Temperature",temperatureC:"Temperature in \xB0C",pressureRatio:"Pressure compared with the start",volumeRatio:"Volume compared with the start",pv:"Pressure \xD7 volume",gasConstant:"pV / (nT) \u2014 the gas constant",rmsSpeed:"Typical speed of the particles",hits:"Particles hitting the piston each second (in the picture)"},view:{particles:"Particles",pressureOption:"Pressure on the piston",isothermal:"Temperature constant: p \xB7 V = constant",isobaric:"Pressure constant: V / T = constant",isochoric:"Volume constant (piston locked): p / T = constant",state:"p = {pressure} \xB7 V = {volume} \xB7 T = {temperature}"},graph:{pv:"The p\u2013V diagram",pt:"Pressure against temperature",vt:"Volume against temperature"},challenge:{boyle:{title:"Three times the pressure",description:"At constant temperature, squeeze the gas until its pressure is three times the starting pressure.",hint:"p\xB7V is constant: you need a third of the volume."},charles:{title:"Twice the volume",description:"With a free piston, heat the gas until its volume doubles.",hint:"V / T is constant: double the kelvin temperature."},sealed:{title:"Heating a closed can",description:"With the piston locked, heat the gas so that its pressure grows at least 1.5 times.",hint:"p / T is constant: raise the kelvin temperature 1.5 times."},twoHundred:{title:"200 kilopascals",description:"Choose a process that ends with a pressure of exactly 200 kPa (\xB11 kPa).",hint:"p = nRT / V. With 0.4 mol at 300 K you need about 5 L."},coolShrink:{title:"Cold shrinks it",description:"With a free piston, cool the gas until its volume is half of the start.",hint:"Halve the kelvin temperature, for example 400 K \u2192 200 K."},fastHelium:{title:"Fast helium",description:"Use helium and end with particles moving at a typical speed of at least 1500 m/s.",hint:"v_rms = \u221A(3RT/M): helium needs about 360 K or more."}}}},a={sim:s};export{a as default,s as sim};
